      return (c && c.content && c.content.parts && c.content.parts[0] && c.content.parts[0].text) || null;
    } catch (e) { if (attempt < MAX_RETRIES) await sleep(1500 * (attempt + 1)); }
  }
  return null;
}
function parse(text, ticker) {
  if (!text) return { ticker, verdict: 'NO', confidence: 0, reason: 'API call failed', red_flags: ['missing_critical_data'], required_confirmation: 'N/A', risk_notes: 'No response', _error: true };
  try {
    const m = text.match(/\{[\s\S]*\}/);
    const p = JSON.parse((m ? m[0] : text).replace(/```json|```/g, '').trim());
    p.verdict = (['YES','NO'].includes(String(p.verdict).toUpperCase())) ? String(p.verdict).toUpperCase() : 'NO';
    if (typeof p.confidence !== 'number') p.confidence = 0;
