}
return [{ json: { geminiResults: results, ...data } }];

// ════════════════════════════════════════════════════════════════
// VERDICT — combine 3 model votes per stock. The council VETOES; the
// quant councilScore RANKS. We keep both clearly separated.
// FIXED: robust merge-input collection (don't clobber baseData).
// ════════════════════════════════════════════════════════════════
const inputs = $input.all();
let claudeResults = [], gptResults = [], geminiResults = [], baseData = {};
for (const inp of inputs) {
  const j = inp.json || {};
  if (Array.isArray(j.claudeResults)) claudeResults = j.claudeResults;
  if (Array.isArray(j.gptResults)) gptResults = j.gptResults;
  if (Array.isArray(j.geminiResults)) geminiResults = j.geminiResults;
  // keep the richest baseData (the one carrying top10)
  if (j.top10 && (!baseData.top10 || j.top10.length >= baseData.top10.length)) baseData = j;
}

const SERIOUS_FLAGS = ['earnings_within_48h', 'poor_liquidity', 'no_clear_stop', 'failed_volume'];
const hasSerious = (f) => (f || []).some(x => SERIOUS_FLAGS.includes(x));

const verdicts = [];
for (let i = 0; i < (baseData.top10 || []).length; i++) {
  const stock = baseData.top10[i];
  const ticker = stock.ticker;
  const c = claudeResults.find(r => r.ticker === ticker) || {};
  const g = gptResults.find(r => r.ticker === ticker) || {};
  const m = geminiResults.find(r => r.ticker === ticker) || {};

  const all3 = [c, g, m];
  const yesVoters = all3.filter(r => r.verdict === 'YES');
  const yesCount = yesVoters.length;
  const confs = all3.map(r => r.confidence).filter(x => typeof x === 'number');
  const avgConfidence = confs.length ? Math.round(confs.reduce((a, b) => a + b, 0) / confs.length) : 0;
  // confidence of only the agreeing models — used for TIER_2 gate so one dissenter can't sink a real majority
  const yesConfs = yesVoters.map(r => r.confidence).filter(x => typeof x === 'number');
  const avgYesConfidence = yesConfs.length ? Math.round(yesConfs.reduce((a, b) => a + b, 0) / yesConfs.length) : 0;
  const uniqueFlags = [...new Set([...(c.red_flags||[]), ...(g.red_flags||[]), ...(m.red_flags||[])])];
  const seriousFlagTriggered = hasSerious(uniqueFlags);
  const seriousFlagSource = uniqueFlags.filter(f => SERIOUS_FLAGS.includes(f));

  let tier, action, sizeMultiplier;
  if (seriousFlagTriggered) { tier = 'FORCE_SKIP'; action = `SKIP — serious flag: ${seriousFlagSource.join(', ')}`; sizeMultiplier = 0; }
  else if (yesCount === 3 && avgConfidence >= 75) { tier = 'TIER_1'; action = 'TRADE CANDIDATE — full size if risk engine passes'; sizeMultiplier = 1.0; }
  else if (yesCount >= 2 && avgYesConfidence >= 70) { tier = 'TIER_2'; action = 'SMALL/WATCH — majority eligible'; sizeMultiplier = 0.5; }
  else if (yesCount >= 2) { tier = 'SKIP'; action = 'SKIP — majority eligible but confidence low'; sizeMultiplier = 0; }
  else if (yesCount === 1) { tier = 'SKIP'; action = 'SKIP — weak agreement (1/3)'; sizeMultiplier = 0; }
  else { tier = 'AVOID'; action = 'AVOID — council rejected'; sizeMultiplier = 0; }

  if (baseData.macro && baseData.macro.regime === 'RED' && sizeMultiplier > 0) {
    tier = 'SKIP'; action = 'SKIP — market regime RED, no new entries'; sizeMultiplier = 0;
  }

  verdicts.push({
    ticker, tier, action, sizeMultiplier, yesCount, avgConfidence, avgYesConfidence,
    claudeVerdict: c.verdict, claudeConfidence: c.confidence, claudeReason: c.reason,
    gptVerdict: g.verdict, gptConfidence: g.confidence, gptReason: g.reason,
    geminiVerdict: m.verdict, geminiConfidence: m.confidence, geminiReason: m.reason,
    allRedFlags: uniqueFlags, seriousFlagTriggered, seriousFlagSource,
    requiredConfirmation: c.required_confirmation || g.required_confirmation || m.required_confirmation || '',
    riskNotes: [c.risk_notes, g.risk_notes, m.risk_notes].filter(Boolean).join(' | '),
    scannerData: stock, councilScore: stock.council_score, grade: stock.grade
  });
}

// RANK by quant councilScore within each tier (idea surfacing), not by vote alone
const tierOrder = { TIER_1: 0, TIER_2: 1, SKIP: 2, AVOID: 3, FORCE_SKIP: 4 };
verdicts.sort((a, b) => (tierOrder[a.tier] - tierOrder[b.tier]) || (b.councilScore - a.councilScore) || (b.avgConfidence - a.avgConfidence));

const tradeCandidates = verdicts.filter(v => v.tier === 'TIER_1');
const watchList = verdicts.filter(v => v.tier === 'TIER_2');
const skipped = verdicts.filter(v => ['SKIP', 'AVOID', 'FORCE_SKIP'].includes(v.tier));

return [{ json: {
  verdicts, tradeCandidates, watchList, skipped,
  summary: { total: verdicts.length, tier1: tradeCandidates.length, tier2: watchList.length, skipped: skipped.length, regime: baseData.macro && baseData.macro.regime, session: baseData.macro && baseData.macro.session },
  macro: baseData.macro, formatted: baseData.formatted, scanTimestamp: baseData.scanTimestamp, verdictTimestamp: new Date().toISOString()
} }];

// ════════════════════════════════════════════════════════════════
// RISK ENGINE — final sizing, no-chase, max trades/day, portfolio heat.
// ════════════════════════════════════════════════════════════════
const data = $input.first().json;
const ACCOUNT = Number($vars.ACCOUNT_SIZE || 25000);
const RISK_PCT = Number($vars.RISK_PCT || 0.01);
const RISK_DOLLARS = Math.round(ACCOUNT * RISK_PCT);
const MAX_TRADES = Number($vars.MAX_TRADES || 3);
const MAX_HEAT = Number($vars.MAX_PORTFOLIO_HEAT || 0.06);
const num = (x, d = 0) => { const n = Number(x); return Number.isFinite(n) ? n : d; };

let heat = 0, approved = 0;
const finalTrades = [], riskRejected = [];

for (const v of (data.tradeCandidates || [])) {
  const s = v.scannerData || {};
  if (approved >= MAX_TRADES) { riskRejected.push({ ...v, riskRejectReason: `Max ${MAX_TRADES} trades/day reached` }); continue; }
  const dist = num(s.distance_from_vwap_pct);
  if (dist > 2.5) { riskRejected.push({ ...v, riskRejectReason: `Overextended ${dist.toFixed(1)}% above VWAP` }); continue; }
  const rr = num(s.reward_risk);
  if (rr < 1.5) { riskRejected.push({ ...v, riskRejectReason: `R/R too low: ${rr}` }); continue; }
  const rps = num(s.risk_per_share);
  if (!(rps > 0)) { riskRejected.push({ ...v, riskRejectReason: 'No valid stop distance' }); continue; }

  const baseRisk = Math.min(RISK_DOLLARS * v.sizeMultiplier, RISK_DOLLARS);
  const shares = Math.floor(baseRisk / rps);
  if (shares < 1) { riskRejected.push({ ...v, riskRejectReason: 'Position rounds to 0 shares' }); continue; }
  const posValue = shares * num(s.price);
  const heatAdd = baseRisk / ACCOUNT;
  if (heat + heatAdd > MAX_HEAT) { riskRejected.push({ ...v, riskRejectReason: `Would exceed ${MAX_HEAT*100}% portfolio heat` }); continue; }

  heat += heatAdd; approved++;
  finalTrades.push({ ...v, riskEngine: {
    shares, riskDollars: Math.round(baseRisk), positionValue: Math.round(posValue),
    riskPct: (heatAdd * 100).toFixed(2), stopLoss: s.stop_loss, entryZone: s.entry_zone,
    tp1: s.tp1, tp2: s.tp2, rewardRisk: rr,
    sizeNote: v.sizeMultiplier < 1 ? `REDUCED (${v.sizeMultiplier*100}% — Tier 2)` : 'FULL (Tier 1)'
  } });
}

return [{ json: {
  finalTrades, riskRejected, watchList: data.watchList, skipped: data.skipped,
  summary: { ...data.summary, finalApproved: finalTrades.length, riskRejected: riskRejected.length, portfolioHeatPct: (heat * 100).toFixed(2) },
  macro: data.macro, formatted: data.formatted, scanTimestamp: data.scanTimestamp, verdictTimestamp: data.verdictTimestamp, riskTimestamp: new Date().toISOString()
} }];

// ════════════════════════════════════════════════════════════════
// FORMAT TELEGRAM — clearly separates RANK (quant) from VOTE (council veto)
// ════════════════════════════════════════════════════════════════
const data = $input.first().json;
const macro = data.macro || {}; const trades = data.finalTrades || []; const watch = data.watchList || []; const s = data.summary || {};
const re = macro.regime === 'GREEN' ? '🟢' : macro.regime === 'RED' ? '🔴' : '🟡';

let msg = `🏛️ *COUNCIL OF AIs v5.0 — TRADE PLAN*\n`;
msg += `_${new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})} | ${macro.session || ''}_\n\n`;
msg += `${re} Regime: *${macro.regime || '?'}* | VIX: ${macro.vixLevel || '?'}\n`;
msg += `SPY $${macro.spyPrice || '?'} (${(macro.spyChg>=0?'+':'')}${macro.spyChg || 0}%) | QQQ $${macro.qqqPrice || '?'}\n`;
msg += `Scanned: ${s.total || 0} ranked | Approved: *${s.finalApproved || 0}*\n\n`;

if (!trades.length) {
  msg += `⚠️ *No trades passed all filters today.*\nCash is a position.\n`;
} else {
  msg += `━━━━━━━━━━━━━━━━━━━\n✅ *TOP IDEAS (${trades.length})* — ranked by quant score\n━━━━━━━━━━━━━━━━━━━\n`;
  for (const t of trades) {
    const r = t.riskEngine;
    msg += `\n🎯 *${t.ticker}* [Grade ${t.grade}] — score ${t.councilScore}\n`;
    msg += `🗳 Council veto: ${t.yesCount}/3 eligible (${t.avgConfidence}% conf) — C:${t.claudeVerdict} G:${t.gptVerdict} Gm:${t.geminiVerdict}\n`;
    msg += `📍 Entry: ${r.entryZone} | 🛑 Stop: $${r.stopLoss} | R/R: ${r.rewardRisk}:1\n`;
    msg += `💰 T1: $${r.tp1} | T2: $${r.tp2}\n`;
    msg += `📏 *${r.shares} sh* = $${r.riskDollars} risk (${r.sizeNote})\n`;
    if (t.allRedFlags.length) msg += `⚠️ Flags: ${t.allRedFlags.join(', ')}\n`;
    if (t.requiredConfirmation) msg += `✅ Confirm: ${t.requiredConfirmation}\n`;
  }
}
if (watch.length) {
  msg += `\n━━━━━━━━━━━━━━━━━━━\n👁 *WATCHLIST (${watch.length})*\n`;
  for (const w of watch.slice(0, 5)) msg += `• *${w.ticker}* [${w.grade}] score ${w.councilScore} — ${w.yesCount}/3\n`;
}
msg += `\n━━━━━━━━━━━━━━━━━━━\n📊 _Score=quant rank (idea). Votes=AI risk veto, NOT a buy signal._\n`;
msg += `⚠️ _Paper trade until 30+ outcomes logged. Verify live VWAP/volume before entry._`;

const truncated = msg.length > 4000 ? msg.substring(0, 3990) + '…' : msg;
return [{ json: { ...data, telegramMessage: truncated } }];

const data = $input.first().json;
const rows = [];
for (const t of [...(data.finalTrades||[]), ...(data.watchList||[]), ...(data.riskRejected||[]), ...(data.skipped||[])]) {
  const s = t.scannerData || {}; const re = t.riskEngine || {};
  rows.push({
    Timestamp: data.scanTimestamp, Ticker: t.ticker, Grade: t.grade || '', Tier: t.tier, Action: t.action,
    QuantScore: t.councilScore, YesVotes: t.yesCount, AvgConfidence: t.avgConfidence,
    Claude: t.claudeVerdict, GPT: t.gptVerdict, Gemini: t.geminiVerdict,
    RedFlags: (t.allRedFlags||[]).join(', '), Price: s.price || '', Entry: s.entry_zone || '',
    Stop: s.stop_loss || '', TP1: s.tp1 || '', TP2: s.tp2 || '', RR: s.reward_risk || '',
    RVOL: s.volume_ratio || '', Catalyst: s.catalyst_tier || '', Shares: re.shares || '',
    RiskDollars: re.riskDollars || '', Regime: (data.macro && data.macro.regime) || '',
    Outcome: 'PENDING', PnL: '', Notes: ''
  });
}
return rows.map(r => ({ json: r }));
